CREATE TABLE IF NOT EXISTS "srm_code_rule" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "rule_code" varchar(64) NOT NULL,
    "rule_name" varchar(128) DEFAULT NULL,
    "target_form" varchar(64) NOT NULL,
    "prefix" varchar(32) NOT NULL,
    "date_pattern" varchar(32) DEFAULT NULL,
    "date_segment_enabled" bit NOT NULL DEFAULT TRUE,
    "serial_width" int NOT NULL,
    "step" int NOT NULL,
    "min_serial" bigint NOT NULL,
    "max_serial" bigint NOT NULL,
    "separator" varchar(8) DEFAULT NULL,
    "enabled" bit NOT NULL DEFAULT TRUE,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_srm_code_rule_tenant_target_form" UNIQUE ("tenant_id", "target_form", "deleted"),
    CONSTRAINT "uk_srm_code_rule_tenant_rule_code" UNIQUE ("tenant_id", "rule_code", "deleted")
);

CREATE TABLE IF NOT EXISTS "srm_code_rule_counter" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "rule_id" bigint NOT NULL,
    "target_form" varchar(64) NOT NULL,
    "period_key" varchar(32) NOT NULL,
    "current_serial" bigint NOT NULL,
    "last_code" varchar(128) DEFAULT NULL,
    "last_generated_at" timestamp DEFAULT NULL,
    "version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_srm_code_rule_counter_tenant_rule_period" UNIQUE ("tenant_id", "rule_id", "period_key", "deleted"),
    CONSTRAINT "uk_srm_code_rule_counter_tenant_last_code" UNIQUE ("tenant_id", "last_code", "deleted")
);

